const SEASON_REGIONS = {"kanto": {"jp": "関東（野田・銚子）", "en": "KANTO", "label": [140.4, 35.8], "short": "野田・銚子", "picks": ["関東"], "desc": "千葉県の野田と銚子は、江戸時代から江戸に醤油を届けてきた日本最大の醤油の産地。キッコーマンとヤマサ、ヒゲタなどの大手が並ぶ。", "pick": "関東"}, "tohoku": {"jp": "東北", "en": "TOHOKU", "label": [140.5, 39.2], "picks": ["東北"], "desc": "寒く長い冬が、塩気が強く色の濃い赤味噌を育てる。伊達政宗が城下で味噌を造らせた仙台味噌や、秋田のハタハタで造る魚醤「しょっつる」が名高い。", "pick": "東北"}, "shinshu": {"jp": "信州（長野）", "en": "SHINSHU", "label": [138.1, 36.2], "short": "信州", "picks": ["甲信越"], "desc": "日本で造られる味噌の約半分を占める、日本一の味噌どころ。淡い黄色で、すっきりとした辛口の米味噌「信州味噌」で知られる。", "pick": "甲信越"}, "hokuriku": {"jp": "北陸（能登）", "en": "HOKURIKU", "label": [136.9, 37.3], "short": "能登", "picks": ["北陸"], "desc": "能登半島では、イカの内臓やイワシで造る魚醤「いしる（いしり）」が受け継がれてきた。", "pick": "北陸"}, "tokai": {"jp": "東海（愛知）", "en": "TOKAI", "label": [137.1, 35.0], "short": "愛知", "picks": ["東海"], "desc": "豆だけで造る八丁味噌などの豆味噌と、たまり醤油、白醤油の故郷。三河の本みりんや、半田の酢造りの伝統もある、発酵調味料の一大産地。", "pick": "東海"}, "kansai": {"jp": "関西（京都・龍野）", "en": "KANSAI", "label": [135.5, 34.9], "short": "京都・龍野", "picks": ["近畿"], "desc": "兵庫県龍野は、色が淡く塩気の強い「淡口醤油」の発祥地。京都では甘い白味噌の西京味噌や、上品な米酢が造られる。", "pick": "近畿"}, "setouchi": {"jp": "瀬戸内（小豆島・讃岐）", "en": "SETOUCHI", "label": [134.2, 34.3], "short": "小豆島", "picks": ["中国・四国"], "desc": "小豆島は、木の樽で醤油を仕込む蔵が今も多く残る醤油の島。香川や徳島では、上品な甘さの砂糖「和三盆」が作られる。", "pick": "中国・四国"}, "kyushu": {"jp": "九州・沖縄", "en": "KYUSHU & OKINAWA", "label": [130.9, 32.4], "short": "九州", "picks": ["九州・沖縄"], "desc": "甘口の醤油と麦味噌の文化。鹿児島の福山では、屋外に並べた壺で黒酢を造る。柚子胡椒も九州生まれ。沖縄はさとうきびの黒糖の産地。", "pick": "九州・沖縄"}, "china": {"jp": "中国", "en": "CHINA", "desc": "醤（ジャン）の故郷。日本の醤油や味噌の元になった調味料が数多くある。四川の豆板醤、北京の甜麺醤、広東のオイスターソース、江蘇の鎮江香醋など、地方ごとに個性豊か。", "pick": "中国"}, "korea": {"jp": "韓国", "en": "KOREA", "desc": "唐辛子と発酵の国。もち米と唐辛子のコチュジャン、大豆のテンジャンなど、「醤（ジャン）」と呼ばれる発酵調味料が食卓の基本。", "pick": "韓国"}, "seasia": {"jp": "東南アジア", "en": "SOUTHEAST ASIA", "desc": "魚醤の文化圏。ベトナムのニョクマム、タイのナンプラーは料理の塩味と旨みの中心。エビを発酵させたペーストや、唐辛子のサンバルも欠かせない。", "pick": "東南アジア"}, "europe": {"jp": "ヨーロッパ", "en": "EUROPE", "desc": "ワインビネガーやバルサミコなどの酢、マスタード、ウスターソース、海の塩など。イタリアのアマルフィ海岸には、古代ローマのガルムの流れをくむ魚醤も残る。", "pick": "ヨーロッパ"}, "americas": {"jp": "アメリカ大陸", "en": "AMERICAS", "desc": "トマトケチャップや、タバスコなどのホットソースの国。唐辛子の原産地である中南米の食文化が、世界中の辛い調味料の元になった。", "pick": "アメリカ大陸"}, "africa": {"jp": "北アフリカ・中東", "en": "NORTH AFRICA", "desc": "唐辛子とスパイスのペースト「ハリッサ」や、ごまのペースト「タヒニ」など、オリーブオイルと合わせて使う調味料が多い。", "pick": "北アフリカ・中東"}};
const SEASON_COUNTRIES = {"japan": {"jp": "日本", "style": "日本", "en": "JAPAN", "mark": [138.5, 36.5], "map": "japan", "regions": ["tohoku", "kanto", "shinshu", "hokuriku", "tokai", "kansai", "setouchi", "kyushu"], "desc": "醤油・味噌・酢・みりんなど、麹の力を借りた発酵調味料の国。地方ごとに好まれる味が違い、「手前味噌」という言葉もあるほど。地図の地方をタップすると、その土地の調味料が表示される。"}, "china": {"jp": "中国", "style": "中国", "en": "CHINA", "mark": [112, 32], "regions": ["china"]}, "korea": {"jp": "韓国", "style": "韓国", "en": "KOREA", "mark": [127.8, 36.5], "regions": ["korea"]}, "seasia": {"jp": "東南アジア", "style": "東南アジア", "en": "SOUTHEAST ASIA", "mark": [105, 13], "regions": ["seasia"]}, "europe": {"jp": "ヨーロッパ", "style": "ヨーロッパ", "en": "EUROPE", "mark": [5, 46], "regions": ["europe"]}, "americas": {"jp": "アメリカ大陸", "style": "アメリカ大陸", "en": "AMERICAS", "mark": [-95, 35], "regions": ["americas"]}, "africa": {"jp": "北アフリカ・中東", "style": "北アフリカ・中東", "en": "NORTH AFRICA", "mark": [9, 34], "regions": ["africa"]}};
