const SEASON_TYPES = [{"id": "shoyu", "name": "醤油", "en": "Soy Sauce", "kind": "しょっぱい・旨い", "home": "日本、中国、東南アジア", "p": [5, 5, 1, 1, 0, 3, 4, 3], "tags": ["大豆", "小麦", "麹", "旨み"], "desc": "大豆と小麦に麹菌を加えた「もろみ」を、塩水の中で半年〜数年発酵・熟成させて搾ったもの。日本では色や造りによって、濃口・淡口・たまり・再仕込み・白の5種類に分けられる。"}, {"id": "gyosho", "name": "魚醤", "en": "Fish Sauce", "kind": "しょっぱい・旨い", "home": "東南アジア、日本、イタリア", "p": [5, 5, 1, 0, 0, 4, 5, 2], "tags": ["魚", "発酵", "旨み", "強い香り"], "desc": "魚を塩に漬けて発酵させ、出てきた液を集めたもの。独特の強い香りがあるが、加熱したり料理に混ぜたりすると深い旨みに変わる。古代ローマの「ガルム」も魚醤の仲間。"}, {"id": "miso", "name": "味噌・醤（ジャン）", "en": "Miso & Fermented Paste", "kind": "しょっぱい・旨い", "home": "日本、中国、韓国", "p": [4, 5, 2, 0, 1, 3, 4, 4], "tags": ["大豆", "麹", "発酵", "コク"], "desc": "大豆に麹と塩を加えて発酵させたペースト状の調味料。日本の味噌は麹の種類で米味噌・麦味噌・豆味噌に分かれる。中国の豆板醤や甜麺醤、韓国のコチュジャンやテンジャンも仲間。"}, {"id": "su", "name": "酢", "en": "Vinegar", "kind": "酸っぱい", "home": "日本、中国、ヨーロッパ", "p": [0, 2, 1, 5, 0, 3, 3, 1], "tags": ["酸味", "さっぱり", "発酵"], "desc": "お酒（アルコール）を酢酸菌で発酵させて造る調味料。米から造る米酢、ぶどうのワインビネガー、りんご酢など、原料のお酒によって香りが変わる。"}, {"id": "mirin", "name": "みりん・料理酒", "en": "Mirin & Cooking Sake", "kind": "甘い", "home": "日本", "p": [0, 3, 5, 0, 0, 2, 2, 3], "tags": ["甘み", "照り", "臭み消し"], "desc": "もち米と米麹を焼酎に漬けて熟成させた甘いお酒「本みりん」や、料理用の日本酒。上品な甘みと照りを出し、煮崩れを防ぎ、魚の臭みを消す。"}, {"id": "sauce", "name": "ソース・たれ", "en": "Sauce", "kind": "混ぜて作る", "home": "イギリス、日本、中国、アメリカ", "p": [3, 4, 3, 3, 1, 4, 2, 4], "tags": ["複雑", "野菜", "果実", "スパイス"], "desc": "野菜や果物、スパイス、醤油や酢などを合わせて作る調味料。イギリス生まれのウスターソースや、日本のお好みソース、中国のオイスターソースなど。"}, {"id": "spicy", "name": "辛味調味料", "en": "Hot Sauce & Condiment", "kind": "辛い", "home": "中国、韓国、東南アジア、中南米、北アフリカ", "p": [3, 2, 1, 2, 5, 4, 2, 2], "tags": ["唐辛子", "辛い", "香り"], "desc": "唐辛子やからし、柚子胡椒など、辛みと香りを加える調味料。世界中に、その土地の料理に合わせた辛い調味料がある。"}, {"id": "salt", "name": "塩・甘味料", "en": "Salt & Sweetener", "kind": "基本の調味料", "home": "世界各地", "p": [3, 1, 2, 0, 0, 1, 0, 1], "tags": ["塩", "砂糖", "ミネラル"], "desc": "味の土台になる塩と砂糖。海水を煮詰めたり天日で干したりする塩、さとうきびから造る黒糖や和三盆など、造り方で味わいが変わる。"}];
